            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Treat phone access, screenshots and diagnostics as part of the secret boundary.", fr: "Considérez l’accès au téléphone, les captures et les diagnostics comme faisant partie de la frontière des secrets."),
            ),
          ],
          visual: GuideVisual(
            kind: "callout",
            key: "mastery.key-security",
            alt: GuideText(en: "OSIA visual explaining keys, quotas and security.", fr: "Visuel OSIA expliquant clés, quotas et sécurité."),
