            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "PC limits follow measured resources and provider policy; mobile has the explicit ten-file, 20 MiB aggregate policy.", fr: "Les limites PC suivent les ressources mesurées et le fournisseur ; le mobile applique explicitement dix fichiers et 20 Mio au total."),
            ),
