          id: "mastery.durable-chat",
          trackId: "master-osia",
          order: 15,
          title: GuideText(en: "Durable Chat execution", fr: "Exécution durable dans Chat"),
          subtitle: GuideText(en: "Chat can carry a bounded multi-action objective without changing mode or exposing a generated task plan.", fr: "Chat peut mener un objectif borné en plusieurs actions sans changer de mode ni afficher un plan de tâches généré."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Describe the objective in Chat and keep its target, constraints and negative instructions explicit. OSIA preserves the selected provider/model, chooses the next applicable action from current evidence, checkpoints uncertain or waiting work, verifies the observed result and continues in the same conversation. Stop targets only that exact turn and run.", fr: "Décrivez l’objectif dans Chat et précisez cible, contraintes et interdictions. OSIA conserve le fournisseur/modèle sélectionné, choisit l’action suivante selon les preuves courantes, sauvegarde les attentes ou incertitudes, vérifie le résultat observé puis continue dans la même conversation. Arrêter ne vise que ce tour et ce run exacts."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Ask Chat to inspect a project and apply approved fixes, then expand Thinking to inspect only real public activity.", fr: "Demandez dans Chat d’inspecter un projet et d’appliquer les corrections approuvées, puis développez Réflexion pour consulter uniquement l’activité publique réelle."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Keep consequential work supervised and preserve backups.", fr: "Surveillez les actions importantes et conservez des sauvegardes."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "mastery.durable-chat",
