        GuideSlide(
          id: "mastery.single-transport",
          trackId: "master-osia",
          order: 34,
          title: GuideText(en: "One committed transport", fr: "Un seul transport engagé"),
          subtitle: GuideText(en: "Only one road may carry application traffic at a time. After sleep or a network change, reconnect attempts are coalesced. OSIA does not switch roads during an active request because replaying part of a response could duplicate work.", fr: "Une seule route transporte les données de l’application à la fois. Après une veille ou un changement de réseau, les reconnexions sont regroupées. OSIA ne change pas de route pendant une demande active afin d’éviter de dupliquer une partie du travail."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "Worked example", fr: "Exemple concret"),
              body: GuideText(en: "At home, the phone may connect over the authenticated private LAN. Away from home, WebRTC may establish a direct path; if it cannot, the end-to-end encrypted relay carries the conversation. The OSIA task still runs on the PC.", fr: "À la maison, le téléphone peut utiliser le réseau local privé authentifié. À distance, WebRTC peut créer une route directe ; sinon, le relais chiffré de bout en bout transporte la conversation. La tâche OSIA s’exécute toujours sur le PC."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "mastery.single-transport",
            alt: GuideText(en: "OSIA visual explaining one committed transport.", fr: "Visuel OSIA expliquant un seul transport engagé."),
