        GuideSlide(
          id: "mastery.workflow-models",
          trackId: "master-osia",
          order: 44,
          title: GuideText(en: "Model workflow", fr: "Parcours modèles"),
          subtitle: GuideText(en: "Models: use manual selection for predictable tests; enable Heavy/Medium chains only when you want automatic routing and have configured each entry. Compare quality, latency and provider usage with the same harmless prompt.", fr: "Modèles : utilisez la sélection manuelle pour des tests prévisibles ; activez les chaînes Lourde/Moyenne seulement après avoir configuré chaque entrée. Comparez qualité, délai et utilisation avec la même demande sans risque."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "One complete workflow", fr: "Un flux complet"),
              body: GuideText(en: "1. On PC, ask OSIA to analyze a local error log without changing files.\n2. Review its diagnosis and choose one proposed fix.\n3. Continue from mobile and ask for a concise execution checklist.\n4. Return to PC for any tool action and verify the final diff/output.", fr: "1. Sur le PC, demander l’analyse d’un journal d’erreurs sans modifier de fichier.\n2. Vérifier le diagnostic et choisir une correction proposée.\n3. Continuer sur mobile et demander une liste d’exécution concise.\n4. Revenir au PC pour toute action d’outil et vérifier le résultat final."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
