    GuideTrack(
      id: "osia-advanced",
      semanticId: "advanced",
      order: 3,
      title: GuideText(en: "OSIA: Advanced Guide", fr: "OSIA : Guide avancé"),
      summary: GuideText(en: "Architecture, protocols, development, security, and project continuation.", fr: "Architecture, protocoles, développement, sécurité et reprise du projet."),
      slides: <GuideSlide>[
        GuideSlide(
          id: "advanced.product-architecture",
          trackId: "osia-advanced",
          order: 1,
          title: GuideText(en: "Product architecture", fr: "Architecture du produit"),
          subtitle: GuideText(en: "OSIA is a PC-first assistant with a mobile control surface and pluggable AI providers.", fr: "OSIA est un assistant centré sur le PC, avec une surface mobile et des fournisseurs d’IA interchangeables."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Execution, durable state and tools stay on the PC. The mobile is a second screen, networking prefers direct authenticated paths, provider adapters isolate external APIs, and the agent invokes only registered tools with execution-integrity barriers.", fr: "L’exécution, l’état durable et les outils restent sur le PC. Le mobile est un second écran, le réseau préfère les chemins directs authentifiés, les adaptateurs isolent les API externes et l’agent n’appelle que les outils enregistrés avec les barrières d’intégrité d’exécution."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Trace any feature through UI, PC state owner, transport, agent/provider and terminal result.", fr: "Suivez toute fonction à travers interface, propriétaire PC, transport, agent/fournisseur et résultat final."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Local-first describes ownership, not a promise that configured cloud providers receive no data.", fr: "Local-first décrit la propriété, pas la promesse qu’aucun fournisseur cloud configuré ne reçoit de données."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.product-architecture",
            alt: GuideText(en: "OSIA visual explaining product architecture.", fr: "Visuel OSIA expliquant architecture du produit."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.repository-topology",
          trackId: "osia-advanced",
          order: 2,
          title: GuideText(en: "Repository topology", fr: "Topologie des dépôts"),
          subtitle: GuideText(en: "Four independently versioned repositories divide product responsibilities.", fr: "Quatre dépôts versionnés indépendamment répartissent les responsabilités du produit."),
          bodyBlocks: <GuideText>[
            GuideText(en: "osia contains the cross-platform PC application; osia-mobile contains Flutter clients; osia-worker contains rendezvous and relay Workers; osia-site contains the public static site and release metadata presentation. Coordinated changes must audit each repository without assuming a shared release number.", fr: "osia contient l’application PC multiplateforme ; osia-mobile les clients Flutter ; osia-worker les Workers de rendez-vous et relais ; osia-site le site statique public et la présentation des métadonnées. Une modification coordonnée audite chaque dépôt sans supposer un numéro commun."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "A transport change normally needs PC, mobile and Worker compatibility review, while a guide-only site explanation may remain read-only.", fr: "Un changement de transport exige normalement une revue PC, mobile et Worker, tandis qu’une explication de guide peut laisser le site en lecture seule."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Record each repository HEAD and divergence separately.", fr: "Consignez séparément le HEAD et la divergence de chaque dépôt."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.repository-topology",
            alt: GuideText(en: "OSIA visual explaining repository topology.", fr: "Visuel OSIA expliquant topologie des dépôts."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.pc-architecture",
          trackId: "osia-advanced",
          order: 3,
          title: GuideText(en: "PC architecture", fr: "Architecture PC"),
          subtitle: GuideText(en: "The PC application combines a Qt interface with local services and an agent runtime.", fr: "L’application PC combine une interface Qt, des services locaux et un agent."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Key modules include osia/gui for Qt, main.py for startup, agent.py for turns, conversation storage, models.py and provider adapters, attachments.py and desktop_attachments.py, vision routing, mcp_client, cron.py, memory.py, LAN/relay/WebRTC modules, updater modules and packaging/windows. Protected parsing and transport contracts require targeted changes only.", fr: "Les modules clés comprennent osia/gui pour Qt, main.py pour le démarrage, agent.py pour les tours, le stockage des conversations, models.py et les adaptateurs, attachments.py et desktop_attachments.py, la vision, mcp_client, cron.py, memory.py, LAN/relais/WebRTC, la mise à jour et packaging/windows. Les contrats protégés exigent des changements ciblés."),
          ],
          callouts: <GuideCallout>[
