              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "When a GUI action changes state, find its signal, service call, persistence file and every caller before editing.", fr: "Quand une action GUI change l’état, trouvez son signal, l’appel de service, le fichier persistant et tous les appelants avant modification."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Module names are navigation aids, not permission to refactor adjacent code.", fr: "Les noms de modules aident à naviguer ; ils n’autorisent pas un refactoring voisin."),
            ),
          ],
          visual: GuideVisual(
