        GuideSlide(
          id: "advanced.mobile-architecture",
          trackId: "osia-advanced",
          order: 4,
          title: GuideText(en: "Mobile architecture", fr: "Architecture mobile"),
          subtitle: GuideText(en: "The Flutter application renders screens while services mirror PC-owned state and select one transport.", fr: "L’application Flutter affiche les écrans tandis que les services reflètent l’état du PC et choisissent un transport."),
          bodyBlocks: <GuideText>[
            GuideText(en: "lib/screens holds user surfaces; WebSocketService is the message facade; transport, LAN, WebRTC and relay services coordinate connectivity; storage keeps pairing and interface preferences; lifecycle, foreground service and notifications handle platform constraints. Android and iOS projects provide native shells, but the mobile is not the conversation source of truth.", fr: "lib/screens contient les surfaces ; WebSocketService est la façade de messages ; les services transport, LAN, WebRTC et relais coordonnent la connexion ; le stockage garde association et préférences ; cycle de vie, service au premier plan et notifications gèrent les contraintes. Android et iOS sont des coques, pas la source des conversations."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Follow a mobile button from screen callback to service frame and PC acknowledgement.", fr: "Suivez un bouton mobile depuis le rappel d’écran jusqu’à la trame de service et l’accusé PC."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A locally cached selection is not automatically authoritative PC configuration.", fr: "Une sélection en cache local n’est pas automatiquement la configuration PC autoritaire."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.mobile-architecture",
            alt: GuideText(en: "OSIA visual explaining mobile architecture.", fr: "Visuel OSIA expliquant architecture mobile."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.worker-architecture",
          trackId: "osia-advanced",
          order: 5,
          title: GuideText(en: "Worker architecture", fr: "Architecture Worker"),
          subtitle: GuideText(en: "Cloudflare Workers provide rendezvous and an E2E-blind WebSocket relay.", fr: "Les Cloudflare Workers fournissent le rendez-vous et un relais WebSocket aveugle au contenu E2E."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The rendezvous Worker maps a derived key to the PC route and relays OAuth callbacks. The relay uses one Durable Object per pair, role-authoritative URLs, WebSocket hibernation, sequence and size guards, priority-aware backpressure and generation replacement. It sees routing metadata and ciphertext, not decrypted conversations, tools, files or audio.", fr: "Le Worker de rendez-vous associe une clé dérivée à la route PC et relaie les retours OAuth. Le relais utilise un Durable Object par paire, des URL autoritaires par rôle, l’hibernation WebSocket, des gardes de séquence/taille, une pression selon priorité et le remplacement de génération. Il voit métadonnées et chiffré, pas le contenu."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Inspect relay policy and endpoint crypto together before changing an envelope field.", fr: "Examinez ensemble politique du relais et crypto des extrémités avant de changer une enveloppe."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Worker routing authority must never become decryption authority.", fr: "L’autorité de routage du Worker ne doit jamais devenir une autorité de déchiffrement."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.worker-architecture",
            alt: GuideText(en: "OSIA visual explaining worker architecture.", fr: "Visuel OSIA expliquant architecture worker."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.message-flow",
          trackId: "osia-advanced",
          order: 6,
          title: GuideText(en: "End-to-end message flow", fr: "Flux de message de bout en bout"),
          subtitle: GuideText(en: "A user request is correlated from its conversation through one terminal result.", fr: "Une demande utilisateur est corrélée depuis sa conversation jusqu’à un résultat final unique."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The UI assigns conversation and request identity, attachments prepare before commit, the PC locks the turn, selects provider/model, assembles context and runs the agent. Tool progress and streamed text carry correlation back to PC and mobile; completion, failure or cancellation seals the turn and releases the lock.", fr: "L’interface attribue conversation et requête, les pièces jointes se préparent avant validation, le PC verrouille le tour, choisit fournisseur/modèle, assemble le contexte et lance l’agent. Progression et texte diffusé reviennent corrélés ; fin, échec ou annulation scellent le tour et libèrent le verrou."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Draw the flow as input → attachment commit → active turn → provider/tools → stream → terminal event.", fr: "Dessinez le flux : entrée → validation des pièces jointes → tour actif → fournisseur/outils → flux → événement final."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Never replay a prior answer as success after an attachment or provider failure.", fr: "Ne rejouez jamais une ancienne réponse comme succès après un échec de fichier ou de fournisseur."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.message-flow",
            alt: GuideText(en: "OSIA visual explaining end-to-end message flow.", fr: "Visuel OSIA expliquant flux de message de bout en bout."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.pairing-protocol",
          trackId: "osia-advanced",
          order: 7,
          title: GuideText(en: "Pairing protocol", fr: "Protocole d’association"),
          subtitle: GuideText(en: "Temporary pairing material establishes trust without publishing the raw secret.", fr: "Le matériel temporaire d’association établit la confiance sans publier le secret brut."),
          bodyBlocks: <GuideText>[
            GuideText(en: "PC and mobile derive a pair identifier and proofs, assert authoritative roles and confirm fresh cryptographic context. Expired or mismatched material fails closed; regenerating the PC token replaces trust and requires pairing again. Reconnect creates a new session or generation rather than accepting stale identity.", fr: "PC et mobile dérivent un identifiant de paire et des preuves, affirment leurs rôles et confirment un contexte cryptographique neuf. Un matériel expiré ou incohérent échoue fermé ; régénérer le jeton remplace la confiance. La reconnexion crée une session ou génération neuve."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Test correct, wrong, expired and replaced pairing paths without logging the secret.", fr: "Testez les chemins correct, erroné, expiré et remplacé sans journaliser le secret."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A token is secret input; its derived identifiers are still sensitive metadata.", fr: "Un jeton est une entrée secrète ; ses identifiants dérivés restent des métadonnées sensibles."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.pairing-protocol",
            alt: GuideText(en: "OSIA visual explaining pairing protocol.", fr: "Visuel OSIA expliquant protocole d’association."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.transport-overview",
          trackId: "osia-advanced",
          order: 8,
          title: GuideText(en: "Direct-first transport overview", fr: "Vue d’ensemble des transports directs"),
          subtitle: GuideText(en: "One authenticated application transport owns the PC bridge at a time.", fr: "Un seul transport applicatif authentifié possède le pont PC à la fois."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Selection tries a provisioned private-LAN WSS path, opens the E2E relay in signaling standby, retries newly provisioned LAN, attempts data-only WebRTC/P2P, then explicitly commits the encrypted relay. The coordinator and OS-level lease prevent two bridges from delivering one turn.", fr: "La sélection essaie le WSS du LAN privé, ouvre le relais E2E en attente de signalisation, retente le LAN nouvellement fourni, essaie WebRTC/P2P pour les données, puis valide explicitement le relais chiffré. Le coordinateur et le verrou système empêchent deux ponts de livrer un tour."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Log the chosen transport and attempt identity, not payload contents.", fr: "Journalisez le transport et l’identité de tentative, pas le contenu."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Relay standby is signaling infrastructure until its application commit succeeds.", fr: "Le relais en attente ne porte que la signalisation jusqu’à validation applicative."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.transport-overview",
            alt: GuideText(en: "OSIA visual explaining direct-first transport overview.", fr: "Visuel OSIA expliquant vue d’ensemble des transports directs."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.lan",
          trackId: "osia-advanced",
          order: 9,
          title: GuideText(en: "LAN transport", fr: "Transport LAN"),
          subtitle: GuideText(en: "The local path uses authenticated WSS on a private IPv4 network.", fr: "Le chemin local utilise WSS authentifié sur un réseau IPv4 privé."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The PC advertises discovery data, binds the private address on port 8766 and presents a self-signed ECDSA certificate whose SHA-256 pin was provisioned inside the E2E channel. The phone accepts only private numeric addresses and the matching pin. Guest isolation, a public network profile or firewall policy can block discovery or connection.", fr: "Le PC annonce la découverte, écoute l’adresse privée sur le port 8766 et présente un certificat ECDSA auto-signé dont l’empreinte SHA-256 a été fournie dans le canal E2E. Le téléphone n’accepte qu’une adresse numérique privée et l’empreinte correspondante. Isolation invité, profil public ou pare-feu peuvent bloquer."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Verify both devices share a trusted private LAN before inspecting fallback transports.", fr: "Vérifiez que les deux appareils partagent un LAN privé de confiance avant les replis."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Do not forward the LAN port to the Internet.", fr: "Ne redirigez pas le port LAN vers Internet."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.lan",
            alt: GuideText(en: "OSIA visual explaining lan transport.", fr: "Visuel OSIA expliquant transport lan."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.webrtc",
          trackId: "osia-advanced",
          order: 10,
          title: GuideText(en: "WebRTC and P2P", fr: "WebRTC et P2P"),
          subtitle: GuideText(en: "WebRTC seeks a direct, ordered and reliable data path across networks.", fr: "WebRTC cherche un chemin de données direct, ordonné et fiable entre réseaux."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The PC creates a fresh offer; mobile answers; bounded SDP and ICE candidates travel only inside relay E2E frames. A single ordered DataChannel then performs another pairing-authenticated E2E handshake before application commit. Failed ICE, authentication, timeout or bridge availability closes that attempt and permits relay fallback.", fr: "Le PC crée une offre neuve ; le mobile répond ; SDP et candidats ICE bornés voyagent uniquement dans les trames E2E du relais. Un DataChannel ordonné réalise un nouvel échange E2E authentifié avant validation. Échec ICE, authentification, délai ou pont ferme la tentative et permet le relais."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Record offer/answer state, candidate summary and failure category without SDP addresses in shared logs.", fr: "Consignez état offre/réponse, résumé des candidats et catégorie d’échec sans adresses SDP dans les journaux partagés."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Every attempt uses fresh generation and cryptographic context.", fr: "Chaque tentative utilise une génération et un contexte cryptographique neufs."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.webrtc",
            alt: GuideText(en: "OSIA visual explaining webrtc and p2p.", fr: "Visuel OSIA expliquant webrtc et p2p."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.ice-stun-turn",
          trackId: "osia-advanced",
          order: 11,
          title: GuideText(en: "ICE, STUN and TURN", fr: "ICE, STUN et TURN"),
          subtitle: GuideText(en: "ICE selects connectivity candidates; STUN discovers mapped addresses; TURN relays WebRTC media or data when direct candidates fail.", fr: "ICE sélectionne des candidats de connexion ; STUN découvre les adresses traduites ; TURN relaie les données WebRTC lorsque le direct échoue."),
          bodyBlocks: <GuideText>[
            GuideText(en: "OSIA persists only validated credential-free STUN URLs and currently defaults to Cloudflare STUN. Optional TURN records require credentials from protected runtime environment configuration and are never stored in ordinary settings. TURN is therefore supported as protected configuration, not configured by default; OSIA’s own E2E relay remains the normal fallback.", fr: "OSIA ne persiste que des URL STUN validées sans identifiants et utilise par défaut le STUN Cloudflare. Les entrées TURN facultatives exigent des identifiants fournis par l’environnement protégé et ne sont jamais stockées dans les réglages. TURN est donc possible mais absent par défaut ; le relais E2E OSIA reste le repli normal."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Differentiate a STUN reachability failure from a relay failure before changing production configuration.", fr: "Distinguez un échec STUN d’un échec du relais avant de changer la production."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Never place TURN credentials in tracked settings or guide examples.", fr: "Ne placez jamais d’identifiants TURN dans des réglages suivis ou des exemples."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.ice-stun-turn",
            alt: GuideText(en: "OSIA visual explaining ice, stun and turn.", fr: "Visuel OSIA expliquant ice, stun et turn."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.relay",
          trackId: "osia-advanced",
          order: 12,
          title: GuideText(en: "OSIA relay fallback", fr: "Relais de secours OSIA"),
          subtitle: GuideText(en: "The public relay becomes the application transport only after direct paths fail and an encrypted commit succeeds.", fr: "Le relais public devient le transport applicatif seulement après l’échec des chemins directs et une validation chiffrée."),
          bodyBlocks: <GuideText>[
            GuideText(en: "A Durable Object routes PC and mobile roles for one pair, enforces monotonic sequences, generations, frame and chunk limits, priorities and backpressure, and hibernates idle sockets. Application frames must be E2E envelopes; plaintext is rejected. Duplicate readiness and commits are idempotent, while stale sessions are superseded.", fr: "Un Durable Object route les rôles PC/mobile d’une paire, impose séquences monotones, générations, limites de trames/fragments, priorités et pression, puis hiberne les sockets inactifs. Les trames applicatives doivent être E2E ; le clair est refusé. Les doublons sont idempotents et les sessions anciennes remplacées."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Exercise reconnect and duplicate messages in tests before changing relay ordering.", fr: "Testez reconnexion et doublons avant de modifier l’ordre du relais."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "The relay can route ciphertext and metadata but cannot decrypt application content.", fr: "Le relais route chiffré et métadonnées sans pouvoir déchiffrer le contenu."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.relay",
            alt: GuideText(en: "OSIA visual explaining osia relay fallback.", fr: "Visuel OSIA expliquant relais de secours osia."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.e2e",
          trackId: "osia-advanced",
          order: 13,
          title: GuideText(en: "End-to-end encryption", fr: "Chiffrement de bout en bout"),
          subtitle: GuideText(en: "Endpoint-only key establishment protects confidentiality, integrity and session identity.", fr: "L’établissement de clés aux extrémités protège confidentialité, intégrité et identité de session."),
          bodyBlocks: <GuideText>[
            GuideText(en: "PC and mobile combine fresh X25519 agreement with pairing-derived material, derive direction-separated keys and nonces, confirm the transcript, then use authenticated ChaCha20-Poly1305 envelopes. Sequence guards reject replay; authenticated metadata binds role, pair, priority and finality. Oversized ciphertext is bounded, hashed and chunked; reconnect rotates context.", fr: "PC et mobile combinent un accord X25519 neuf au matériel dérivé de l’association, dérivent clés et nonces par direction, confirment la transcription puis utilisent des enveloppes ChaCha20-Poly1305 authentifiées. Les séquences bloquent le rejeu ; les métadonnées lient rôle, paire, priorité et finalité. Le chiffré volumineux est borné, haché et fragmenté ; la reconnexion renouvelle le contexte."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Use deterministic cross-language vectors to verify both endpoints without exposing production secrets.", fr: "Utilisez des vecteurs déterministes interlangages sans exposer de secrets de production."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Logs may name an error category or shortened key identifier, never key material or plaintext.", fr: "Les journaux peuvent nommer une catégorie ou un identifiant raccourci, jamais une clé ni du clair."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.e2e",
            alt: GuideText(en: "OSIA visual explaining end-to-end encryption.", fr: "Visuel OSIA expliquant chiffrement de bout en bout."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.handshake",
          trackId: "osia-advanced",
          order: 14,
          title: GuideText(en: "Handshake state machine", fr: "Machine d’état de négociation"),
          subtitle: GuideText(en: "Confirmed E2E identity and transport readiness are separate states.", fr: "L’identité E2E confirmée et la disponibilité du transport sont des états distincts."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Relay sessions exchange E2E_HELLO and E2E_READY, then MOBILE_READY and PC_READY describe routable readiness. Direct transports add their own hello, ready and commit sequence tied to attempt and generation. Exact fields, context identity, monotonically ordered messages and duplicate suppression make reconnect deterministic.", fr: "Les sessions relais échangent E2E_HELLO et E2E_READY, puis MOBILE_READY et PC_READY décrivent la disponibilité. Les transports directs ajoutent hello, ready et commit liés à la tentative et génération. Champs exacts, identité de contexte, ordre monotone et suppression des doublons rendent la reconnexion déterministe."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Model each transition and reject a frame that arrives before its prerequisite state.", fr: "Modélisez chaque transition et refusez une trame arrivée avant son état préalable."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Use only confirmed current message names in documentation and tests.", fr: "N’utilisez dans documentation et tests que les noms de messages confirmés."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.handshake",
            alt: GuideText(en: "OSIA visual explaining handshake state machine.", fr: "Visuel OSIA expliquant machine d’état de négociation."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.correlation",
          trackId: "osia-advanced",
          order: 15,
          title: GuideText(en: "Conversation and turn correlation", fr: "Corrélation conversation et tour"),
          subtitle: GuideText(en: "Stable identities keep concurrent UI events attached to the correct request.", fr: "Des identités stables rattachent les événements d’interface à la bonne requête."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Conversation ID selects history; request and turn IDs bind input, attachment batch, progress, tool calls, streamed deltas and terminal event. The active-turn lock blocks overlap. Replay guards and idempotent acknowledgements prevent duplicate delivery, while retry creates an intentional new attempt after the old terminal state.", fr: "L’identifiant de conversation choisit l’historique ; requête et tour lient entrée, lot de fichiers, progression, outils, fragments de réponse et événement final. Le verrou bloque le chevauchement. Les gardes anti-rejeu et accusés idempotents évitent les doublons ; Réessayer crée une nouvelle tentative après la fin."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Assert exactly one terminal event and one committed user turn in correlation tests.", fr: "Vérifiez exactement un événement final et un tour utilisateur validé dans les tests."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Never infer success from a stale buffered answer.", fr: "Ne déduisez jamais un succès d’une ancienne réponse en tampon."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.correlation",
            alt: GuideText(en: "OSIA visual explaining conversation and turn correlation.", fr: "Visuel OSIA expliquant corrélation conversation et tour."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.attachments",
          trackId: "osia-advanced",
          order: 16,
          title: GuideText(en: "Attachments", fr: "Pièces jointes"),
          subtitle: GuideText(en: "Attachments are validated and committed before the agent receives a turn.", fr: "Les pièces jointes sont validées et engagées avant que l’agent reçoive le tour."),
          bodyBlocks: <GuideText>[
            GuideText(en: "PC picking creates an ordered draft and validates again at send time. Mobile copies private selections, enforces ten files and a 20 MiB aggregate, emits 20 KiB chunks with size and SHA-256, and commits only after PC reassembly. Shared checks cover MIME, magic bytes, order, cancellation, temporary cleanup and safe names that cannot traverse paths; a transport change aborts the batch.", fr: "Sur PC, la sélection crée un brouillon ordonné puis revalide à l’envoi. Le mobile copie en privé, impose dix fichiers et 20 Mio au total, envoie des fragments de 20 Kio avec taille et SHA-256, puis engage après réassemblage PC. Les contrôles couvrent MIME, octets magiques, ordre, annulation, nettoyage et noms sans traversée ; changer de transport annule le lot."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Test a valid mixed batch, wrong hash, duplicate chunk, cancellation and reconnect before commit.", fr: "Testez lot mixte valide, mauvais hash, fragment dupliqué, annulation et reconnexion avant validation."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A failed batch must not start the model or replay a previous answer.", fr: "Un lot échoué ne doit ni lancer le modèle ni rejouer une réponse précédente."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.attachments",
            alt: GuideText(en: "OSIA visual explaining attachments.", fr: "Visuel OSIA expliquant pièces jointes."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.vision",
          trackId: "osia-advanced",
          order: 17,
          title: GuideText(en: "Vision inputs", fr: "Entrées de vision"),
          subtitle: GuideText(en: "Image delivery depends on both adapter format and model capability metadata.", fr: "La livraison d’image dépend du format de l’adaptateur et des capacités du modèle."),
          bodyBlocks: <GuideText>[
            GuideText(en: "ChatGPT Account uses its localImage input path; Google and OpenAI-compatible adapters build their supported image content blocks. Provider and model preflight validates MIME and vision support before network work. Unknown capability fails closed, unsupported combinations return a clear error, no silent OCR substitute is invented, and image blocks remain current-turn only.", fr: "Compte ChatGPT utilise son chemin localImage ; Google et les adaptateurs compatibles OpenAI construisent leurs blocs d’image pris en charge. Le préflight valide MIME et vision avant le réseau. Une capacité inconnue échoue fermée, une combinaison incompatible donne une erreur claire, aucun OCR silencieux n’est inventé et l’image reste limitée au tour courant."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Run adapter-structure tests with synthetic images and verify persisted history contains no image block.", fr: "Testez la structure des adaptateurs avec des images fictives et vérifiez l’absence de bloc image dans l’historique persistant."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Model names alone are not proof of vision support.", fr: "Le nom d’un modèle ne prouve pas sa compatibilité vision."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.vision",
            alt: GuideText(en: "OSIA visual explaining vision inputs.", fr: "Visuel OSIA expliquant entrées de vision."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.provider-architecture",
          trackId: "osia-advanced",
          order: 18,
          title: GuideText(en: "Provider architecture", fr: "Architecture des fournisseurs"),
          subtitle: GuideText(en: "Adapters normalize different authentication, streaming, tool and image APIs behind one agent contract.", fr: "Les adaptateurs normalisent authentification, streaming, outils et images derrière un contrat d’agent commun."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The registry covers ChatGPT Account/App Server, native Google behavior and API-key providers including Anthropic, OpenAI-compatible OpenAI/xAI/DeepSeek paths, Groq and Mistral where exposed. Each adapter owns request shape, streaming parsing, tool support, image encoding and error classification. Quota and retry behavior must preserve the provider’s real status.", fr: "Le registre couvre Compte ChatGPT/App Server, Google natif et les fournisseurs à clé exposés, dont Anthropic, les chemins compatibles OpenAI pour OpenAI/xAI/DeepSeek, Groq et Mistral. Chaque adaptateur possède forme de requête, flux, outils, images et classification d’erreurs. Quotas et tentatives doivent préserver l’état réel."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Add adapter tests before advertising a model capability in the registry.", fr: "Ajoutez des tests d’adaptateur avant d’annoncer une capacité dans le registre."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Do not generalize one OpenAI-compatible behavior to every provider without evidence.", fr: "Ne généralisez pas un comportement compatible OpenAI à tous les fournisseurs sans preuve."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.provider-architecture",
            alt: GuideText(en: "OSIA visual explaining provider architecture.", fr: "Visuel OSIA expliquant architecture des fournisseurs."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.provider-hierarchy",
          trackId: "osia-advanced",
          order: 19,
          title: GuideText(en: "Provider and API hierarchy", fr: "Hiérarchie des fournisseurs et API"),
          subtitle: GuideText(en: "Automatic hierarchy routes classified work through ordered provider:model entries.", fr: "La hiérarchie automatique route le travail classé dans une liste ordonnée fournisseur:modèle."),
          bodyBlocks: <GuideText>[
            GuideText(en: "When enabled, Heavy and Medium chains are tried in user order and the manually selected model is the final fallback. Key rotation precedes model fallback for technical errors. Hierarchy switches only on authentication, quota, timeout, connection or server failures; content/client errors do not switch, and no fallback occurs after output streaming starts. Endpoint fallback is a single transport retry with the same key and model.", fr: "Lorsqu’elle est active, les chaînes Lourde et Moyenne suivent l’ordre choisi et le modèle manuel reste le dernier repli. La rotation de clés précède le repli de modèle pour les erreurs techniques. La hiérarchie change seulement pour authentification, quota, délai, connexion ou serveur ; les erreurs de contenu ne changent pas, ni après le début du flux. Le repli d’endpoint est une unique tentative de transport avec même clé et modèle."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Configure two harmless entries, simulate a technical first failure, then verify the second receives no duplicate streamed turn.", fr: "Configurez deux entrées sans risque, simulez un premier échec technique et vérifiez l’absence de tour dupliqué."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "ChatGPT Account follows its configured position; it is not silently always first.", fr: "Compte ChatGPT suit sa position configurée ; il n’est pas secrètement toujours prioritaire."),
            ),
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.provider-hierarchy",
            alt: GuideText(en: "OSIA visual explaining provider and api hierarchy.", fr: "Visuel OSIA expliquant hiérarchie des fournisseurs et api."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.model-capabilities",
          trackId: "osia-advanced",
          order: 20,
          title: GuideText(en: "Model hierarchy and capabilities", fr: "Hiérarchie et capacités des modèles"),
          subtitle: GuideText(en: "The model registry records capabilities used for safe routing and UI controls.", fr: "Le registre des modèles décrit les capacités utilisées pour le routage sûr et les contrôles UI."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Metadata identifies provider, reasoning support, vision and tool compatibility. The provider/model selected in Chat remains authoritative for that entire turn, including durable execution, recovery and resume; voice may expose its documented selector. Heavy/Medium hierarchy handles classified tasks, while an unknown image capability fails closed instead of guessing.", fr: "Les métadonnées indiquent fournisseur, raisonnement, vision et outils. Le fournisseur/modèle sélectionné dans Chat reste l’autorité pendant tout le tour, y compris l’exécution durable, la récupération et la reprise ; la voix peut proposer son sélecteur documenté. La hiérarchie Lourde/Moyenne gère les tâches classées et une capacité image inconnue échoue fermée."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Validate registry metadata, UI availability and adapter behavior as one change.", fr: "Validez ensemble métadonnées, disponibilité UI et comportement de l’adaptateur."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Never reintroduce an artificial global response-token ceiling.", fr: "Ne réintroduisez jamais un plafond global artificiel de jetons de réponse."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.model-capabilities",
            alt: GuideText(en: "OSIA visual explaining model hierarchy and capabilities.", fr: "Visuel OSIA expliquant hiérarchie et capacités des modèles."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.agent-runtime",
          trackId: "osia-advanced",
          order: 21,
          title: GuideText(en: "Agent runtime", fr: "Exécution de l’agent"),
          subtitle: GuideText(en: "The agent assembles bounded context, calls one provider and executes registered tools until a terminal result.", fr: "L’agent assemble un contexte borné, appelle un fournisseur et exécute des outils enregistrés jusqu’au résultat final."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Prompt assembly combines conversation, selected memory, personality/skills, system facts and current attachments. Provider output may stream text and tool calls; parsing occurs before raw tags are stripped, effect-integrity barriers protect sensitive operations, and anti-loop detectors plus a per-turn time limit stop repeated or stalled behavior. The terminal contract must return useful text or an explicit ERROR state.", fr: "L’assemblage combine conversation, mémoire sélectionnée, personnalité/compétences, faits système et pièces jointes courantes. Le fournisseur diffuse texte et appels d’outils ; l’analyse précède le retrait des balises brutes, les barrières d’intégrité d’effet protègent les opérations sensibles, et anti-boucle plus limite de tour arrêtent les répétitions. Le contrat final renvoie un texte utile ou un état ERROR explicite."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Test plain text, native and XML tool calls, denial, loop detection and provider failure without changing protected parser code.", fr: "Testez texte, appels natifs et XML, refus, boucle et échec fournisseur sans modifier l’analyseur protégé."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Parsing, execution and stripping order is an architectural contract.", fr: "L’ordre analyse, exécution puis retrait est un contrat architectural."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.agent-runtime",
            alt: GuideText(en: "OSIA visual explaining agent runtime.", fr: "Visuel OSIA expliquant exécution de l’agent."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.durable-chat",
          trackId: "osia-advanced",
          order: 22,
          title: GuideText(en: "Unified Chat execution internals", fr: "Internes de l’exécution Unified Chat"),
          subtitle: GuideText(en: "A durable action remains one Chat turn governed by its immutable GoalContract and current evidence.", fr: "Une action durable reste un seul tour Chat régi par son GoalContract immuable et les preuves courantes."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Each iteration restores the exact conversation/request/turn/run and provider/model identity, reduces the capability graph to applicable choices, validates one next semantic action, records its attempt and observation, verifies postconditions, then decides again. Waiting, cancellation, unknown-effect reconciliation and terminality are checkpointed without turning private reasoning into a plan or task list. Legacy pre-Chat checkpoints keep a read-only compatibility loader and their safety barriers, but no new request can create one.", fr: "Chaque itération restaure les identités exactes conversation/requête/tour/run et fournisseur/modèle, réduit le graphe aux capacités applicables, valide une action sémantique suivante, enregistre tentative et observation, vérifie les postconditions puis décide à nouveau. Attente, annulation, réconciliation d’effet inconnu et finalité sont sauvegardées sans transformer le raisonnement privé en plan ou liste de tâches. Les anciens points pré-Chat conservent un chargeur compatible en lecture seule et leurs barrières, mais aucune nouvelle demande n’en crée."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Interrupt after one verified action, resume, and confirm completed effects are reconciled instead of replayed.", fr: "Interrompez après une action vérifiée, reprenez et confirmez que les effets accomplis sont réconciliés plutôt que rejoués."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Unattended MCP writes can only fail on technical errors or system-destruction protection; no permission gate exists.", fr: "Les écritures MCP sans surveillance ne peuvent échouer que sur une erreur technique ou la protection contre la destruction du système ; aucune autorisation n’existe."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.durable-chat",
            alt: GuideText(en: "OSIA visual explaining unified chat execution internals.", fr: "Visuel OSIA expliquant internes de l’exécution unified chat."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.computer-use",
          trackId: "osia-advanced",
          order: 23,
          title: GuideText(en: "Computer use internals", fr: "Internes du contrôle de l’ordinateur"),
          subtitle: GuideText(en: "Computer use escalates from stable integrations to less certain visual interaction.", fr: "Le contrôle de l’ordinateur progresse des intégrations stables vers l’interaction visuelle moins certaine."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Priority is API or command integration, URL/deep link, browser DOM and accessible names, native accessibility/UI Automation, keyboard navigation, then screenshot vision and coordinates. Browser sessions use isolated profiles and one managed launch path. Every action should observe resulting process, window, DOM or file state, and sensitive actions keep effect-integrity barriers.", fr: "La priorité est API ou commande, URL/lien profond, DOM du navigateur et noms accessibles, accessibilité/UI Automation native, clavier, puis vision et coordonnées. Les sessions navigateur utilisent des profils isolés et un lancement géré. Chaque action observe ensuite processus, fenêtre, DOM ou fichier, et les actions sensibles gardent les barrières d’intégrité d’effet."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Prefer a named button in the accessibility tree over a coordinate from an old screenshot.", fr: "Préférez un bouton nommé dans l’arbre d’accessibilité à une coordonnée d’ancienne capture."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Coordinate confidence drops when scale, window position or content changes.", fr: "La confiance des coordonnées baisse quand échelle, position ou contenu changent."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.computer-use",
            alt: GuideText(en: "OSIA visual explaining computer use internals.", fr: "Visuel OSIA expliquant internes du contrôle de l’ordinateur."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.cron",
          trackId: "osia-advanced",
          order: 24,
          title: GuideText(en: "Scheduled tasks and cron", fr: "Tâches planifiées et cron"),
          subtitle: GuideText(en: "The PC scheduler persists local-wall-clock jobs and polls for due work.", fr: "Le planificateur PC persiste des tâches en heure locale et recherche les échéances."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Supported syntax covers every N minutes/hours/days, every N days at a time, daily at a time and an ISO one-shot. Weekly syntax is not supported. One-shots disable after firing; recurring jobs can be edited, toggled or deleted and may bind conversation/model. Startup schedules the next occurrence rather than catching up missed work, so sleep or downtime skips past slots; a busy execution remains retryable.", fr: "La syntaxe couvre toutes les N minutes/heures/jours, tous les N jours à une heure, quotidien à une heure et un ISO ponctuel. L’hebdomadaire n’est pas pris en charge. Un ponctuel se désactive ; les récurrents sont modifiables et peuvent lier conversation/modèle. Au démarrage, la prochaine occurrence est calculée sans rattraper les créneaux manqués ; une exécution occupée reste retentable."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Test parsing at timezone and day boundaries with a fake clock, then verify notification and mobile mirror events.", fr: "Testez l’analyse aux limites de fuseau et de jour avec une horloge simulée, puis notifications et miroir mobile."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "The scheduler cannot wake a sleeping PC by itself.", fr: "Le planificateur ne peut pas réveiller seul un PC endormi."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.cron",
            alt: GuideText(en: "OSIA visual explaining scheduled tasks and cron.", fr: "Visuel OSIA expliquant tâches planifiées et cron."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.mcp",
          trackId: "osia-advanced",
          order: 25,
          title: GuideText(en: "MCP architecture", fr: "Architecture MCP"),
          subtitle: GuideText(en: "MCP connects external tool servers through catalog or custom configurations.", fr: "MCP connecte des serveurs d’outils externes via le catalogue ou des configurations personnalisées."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Supported transports are stdio and streamable HTTP; legacy SSE is recognized but unsupported. Catalog entries define health and auth: OAuth may use Dynamic Client Registration or a static client, bearer tokens are validated, and custom connectors remain explicit. Connected tools are injected as namespaced agent tools. Lifecycle covers connect, cancel, disconnect, revoke and reconnect; mobile mirrors status and results.", fr: "Les transports pris en charge sont stdio et HTTP streamable ; SSE ancien est reconnu mais non pris en charge. Le catalogue définit santé et auth : OAuth peut utiliser l’enregistrement dynamique ou un client statique, les jetons sont validés et les connecteurs personnalisés explicites. Les outils sont injectés avec namespace. Le cycle couvre connexion, annulation, déconnexion, révocation et reconnexion ; le mobile reflète l’état."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Test a read tool, an annotated write, OAuth cancellation and restart reconnect with sanitized fixtures.", fr: "Testez lecture, écriture annotée, annulation OAuth et reconnexion après redémarrage avec données fictives."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Catalog presence, suggestability and current connectability are different states.", fr: "Présence au catalogue, proposition et connexion actuelle sont des états différents."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.mcp",
            alt: GuideText(en: "OSIA visual explaining mcp architecture.", fr: "Visuel OSIA expliquant architecture mcp."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.memory-persistence",
          trackId: "osia-advanced",
          order: 26,
          title: GuideText(en: "Memory and persistence", fr: "Mémoire et persistance"),
          subtitle: GuideText(en: "Conversation history, selected memory and runtime state have separate persistence contracts.", fr: "Historique, mémoire sélectionnée et état d’exécution ont des contrats de persistance séparés."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The installed profile uses the resolved user data directory; source mode may use a project config only when its settings file exists. Conversations, memory JSON with atomic backup, settings, ignored API-key and OAuth stores, durable Chat state, legacy execution checkpoints, cron jobs, LAN identity and guide progress remain PC-owned. Mobile stores pairing plus interface preferences. Migration validates IDs and corruption falls back safely without reopening first-run UI.", fr: "Le profil installé utilise le dossier utilisateur résolu ; le mode source peut utiliser config du projet si settings existe. Conversations, mémoire JSON atomique, réglages, magasins ignorés de clés/OAuth, état durable de Chat, anciens points d’exécution, tâches, identité LAN et progression restent PC. Le mobile garde association et préférences. La migration valide les ID et la corruption retombe sûrement sans rouvrir le premier lancement."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Test source and installed path resolution with temporary generic directories, never a personal path.", fr: "Testez la résolution source/installée avec des dossiers temporaires génériques, jamais un chemin personnel."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Deleting mobile data does not delete PC history or memory.", fr: "Supprimer les données mobiles ne supprime pas l’historique ni la mémoire PC."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.memory-persistence",
            alt: GuideText(en: "OSIA visual explaining memory and persistence.", fr: "Visuel OSIA expliquant mémoire et persistance."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.configuration-secrets",
          trackId: "osia-advanced",
          order: 27,
          title: GuideText(en: "Configuration and secrets", fr: "Configuration et secrets"),
          subtitle: GuideText(en: "Configuration is layered so shareable defaults never contain private credentials.", fr: "La configuration est organisée en couches afin que les valeurs partageables ne contiennent jamais d’identifiants privés."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Tracked examples document shape and safe defaults; ignored profile files hold real settings, API keys and OAuth state. Android signing keys, Apple signing material, service accounts, R2 credentials and deployment tokens stay outside Git and enter only through approved local files, secret stores or environment variables. Logs, fixtures and screenshots must redact tokens and personal paths.", fr: "Les exemples suivis documentent la forme et les valeurs sûres ; les fichiers de profil ignorés contiennent les vrais réglages, clés API et états OAuth. Les clés de signature Android, éléments Apple, comptes de service, identifiants R2 et jetons de déploiement restent hors de Git et passent uniquement par des fichiers locaux approuvés, magasins secrets ou variables d’environnement. Journaux, fixtures et captures doivent masquer jetons et chemins personnels."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Use a placeholder in an example file, inject a disposable test secret locally, then inspect the staged diff before committing.", fr: "Placez un substitut dans le fichier d’exemple, injectez localement un secret de test jetable, puis inspectez le diff indexé avant validation."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A masked field is a display safeguard, not proof that no raw secret exists in authenticated runtime memory.", fr: "Un champ masqué protège l’affichage ; il ne prouve pas qu’aucun secret brut n’existe dans la mémoire d’exécution authentifiée."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.configuration-secrets",
            alt: GuideText(en: "OSIA visual explaining configuration and secrets.", fr: "Visuel OSIA expliquant configuration et secrets."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.development-environment",
          trackId: "osia-advanced",
          order: 28,
          title: GuideText(en: "Development environment", fr: "Environnement de développement"),
          subtitle: GuideText(en: "Reproducible development starts with the repository’s documented toolchain and isolated dependencies.", fr: "Un développement reproductible commence par la chaîne d’outils documentée du dépôt et des dépendances isolées."),
          bodyBlocks: <GuideText>[
            GuideText(en: "PC work uses PowerShell, a supported Python virtual environment and Qt dependencies; mobile uses the validated Flutter/Dart toolchain with Android SDK, Java and Gradle; Worker and site tooling use their declared Node packages and Wrangler where applicable. Resolve paths dynamically, keep generated caches out of source control, and record tool versions in release evidence rather than hard-coding them into timeless guidance.", fr: "Le PC utilise PowerShell, un environnement virtuel Python pris en charge et les dépendances Qt ; le mobile utilise la chaîne Flutter/Dart validée avec SDK Android, Java et Gradle ; Worker et site suivent leurs paquets Node déclarés et Wrangler si nécessaire. Résolvez les chemins dynamiquement, excluez les caches générés du suivi et consignez les versions dans les preuves de livraison plutôt que dans un guide intemporel."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "From a fresh clone, create the prescribed environments, restore locked dependencies and run the smallest import or analysis check before editing.", fr: "Depuis un clone neuf, créez les environnements prescrits, restaurez les dépendances verrouillées et lancez le plus petit test d’import ou d’analyse avant toute modification."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A tool installed globally can hide a missing repository dependency.", fr: "Un outil installé globalement peut masquer une dépendance manquante du dépôt."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.development-environment",
            alt: GuideText(en: "OSIA visual explaining development environment.", fr: "Visuel OSIA expliquant environnement de développement."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.takeover-orient",
          trackId: "osia-advanced",
          order: 29,
          title: GuideText(en: "Takeover: orient", fr: "Reprise : s’orienter"),
          subtitle: GuideText(en: "A disciplined takeover makes repository state, running services and release evidence explicit before any edit. 1. Read the request and repository rules. 2. Record every repository path and allowed scope. 3. Capture HEAD, branch, status, index and upstream divergence. 4. Classify existing changes as user-owned or task-owned.", fr: "Une reprise disciplinée rend explicites l’état des dépôts, les services actifs et les preuves de livraison avant toute modification. 1. Lire la demande et les règles. 2. Noter chaque dépôt et le périmètre autorisé. 3. Relever HEAD, branche, état, index et divergence. 4. Classer les changements existants."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.takeover-orient",
            alt: GuideText(en: "OSIA visual explaining takeover: orient.", fr: "Visuel OSIA expliquant reprise : s’orienter."),
            asset: null,
          ),
