          title: GuideText(en: "Takeover: verify", fr: "Reprise : vérifier"),
          subtitle: GuideText(en: "5. Audit relevant processes and services. 6. Inspect architecture and all call sites. 7. Build a source-backed behavior matrix. 8. Define the smallest cross-platform change.", fr: "5. Auditer processus et services. 6. Étudier architecture et appelants. 7. Établir une matrice sourcée. 8. Définir le changement multiplateforme minimal."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Practice on a disposable clone at C:\\path\\to\\osia and stop if a protected or user-owned change overlaps the task.", fr: "Exercez-vous sur un clone jetable dans C:\\path\\to\\osia et arrêtez-vous si un changement protégé ou appartenant à l’utilisateur chevauche la tâche."),
            ),
          ],
          visual: GuideVisual(
