        GuideSlide(
          id: "advanced.takeover-handoff",
          trackId: "osia-advanced",
          order: 31,
          title: GuideText(en: "Takeover: hand off", fr: "Reprise : transmettre"),
          subtitle: GuideText(en: "9. Implement without touching protected contracts. 10. Run syntax, import, focused and adjacent tests. 11. Perform an adversarial correctness, regression and policy review. 12. Stage explicitly, verify the exact diff, commit and build from the committed snapshot.", fr: "9. Implémenter sans toucher aux contrats protégés. 10. Tester syntaxe, imports, cible et voisinage. 11. Mener une revue adversariale. 12. Indexer explicitement, vérifier le diff, valider et construire depuis le commit."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A clean-looking worktree does not replace recording the commit and upstream relationship.", fr: "Un arbre apparemment propre ne remplace pas le relevé du commit et de sa relation avec l’amont."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
