        GuideSlide(
          id: "advanced.safe-modification",
          trackId: "osia-advanced",
          order: 32,
          title: GuideText(en: "Safe modification workflow", fr: "Flux de modification sûr"),
          subtitle: GuideText(en: "Safe changes begin with evidence, preserve contracts and finish with an exact staged diff.", fr: "Les changements sûrs commencent par des preuves, préservent les contrats et finissent par un diff indexé exact."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Reproduce or trace the behavior, identify root cause and every caller, then edit only necessary functions. Preserve parser order, anti-loop, key rotation, configuration resolution, WebSocket contracts and platform guards. Never clean a shared tree with destructive reset. Run targeted and adjacent checks, inspect generated artifacts physically, review from correctness, regression and instruction angles, then stage named paths and compare index against intent.", fr: "Reproduisez ou tracez le comportement, trouvez la cause et tous les appelants, puis ne modifiez que les fonctions nécessaires. Préservez ordre d’analyse, anti-boucle, rotation de clés, résolution de configuration, contrats WebSocket et gardes de plateforme. Ne nettoyez jamais un arbre partagé par réinitialisation destructive. Testez cible et voisinage, inspectez physiquement les artefacts, menez la revue multi-angle, indexez les chemins nommés et comparez l’index à l’intention."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "For a two-file fix, stage those two paths explicitly and prove no third path appears in the cached diff.", fr: "Pour un correctif à deux fichiers, indexez explicitement ces deux chemins et prouvez qu’aucun troisième n’apparaît dans le diff indexé."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Passing tests do not authorize unrelated cleanup or refactoring.", fr: "Des tests réussis n’autorisent ni nettoyage ni refactoring hors périmètre."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.safe-modification",
            alt: GuideText(en: "OSIA visual explaining safe modification workflow.", fr: "Visuel OSIA expliquant flux de modification sûr."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.testing-strategy",
          trackId: "osia-advanced",
          order: 33,
          title: GuideText(en: "Testing strategy", fr: "Stratégie de test"),
          subtitle: GuideText(en: "OSIA testing combines fast contract tests with physical checks at system boundaries.", fr: "Les tests d’OSIA combinent contrats rapides et contrôles physiques aux frontières du système."),
          bodyBlocks: <GuideText>[
            GuideText(en: "PC changes need syntax/import checks plus focused and adjacent pytest suites; Flutter changes need formatting, static analysis, unit/widget tests and release builds. Worker and site changes use their declared checks. Transport and end-to-end tests cover authentication, sequencing, disconnects, replay, fallback and E2E opacity with deterministic fakes. Attachment tests cover limits, hashes, MIME, cancellation and atomic commit. Frozen-app, package and security checks validate the actual artifact, not merely source behavior.", fr: "Les changements PC exigent syntaxe/imports puis tests pytest ciblés et voisins ; Flutter exige formatage, analyse statique, tests unitaires/widgets et builds release. Worker et site suivent leurs contrôles déclarés. Les tests transport et bout en bout couvrent authentification, séquences, déconnexions, rejeu, repli et opacité E2E avec des doublures déterministes. Les pièces jointes couvrent limites, hash, MIME, annulation et validation atomique. Les contrôles frozen, paquet et sécurité valident l’artefact réel."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Inject a fake clock and transport to prove one terminal event, then repeat the critical path on the packaged binary.", fr: "Injectez une horloge et un transport fictifs pour prouver un seul événement final, puis rejouez le chemin critique sur le binaire empaqueté."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A mocked source test cannot prove signing, native libraries or installer contents.", fr: "Un test source simulé ne prouve ni signature, ni bibliothèques natives, ni contenu de l’installateur."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.testing-strategy",
            alt: GuideText(en: "OSIA visual explaining testing strategy.", fr: "Visuel OSIA expliquant stratégie de test."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.windows-packaging",
          trackId: "osia-advanced",
          order: 34,
          title: GuideText(en: "Windows packaging", fr: "Empaquetage Windows"),
          subtitle: GuideText(en: "A Windows release is produced from a clean committed snapshot and validated at every packaging layer.", fr: "Une version Windows est produite depuis un instantané validé propre et contrôlée à chaque couche d’empaquetage."),
          bodyBlocks: <GuideText>[
            GuideText(en: "The repository build creates a PyInstaller onedir application, runs package smoke checks and validates GUI startup before an optional Inno Setup installer. Release metadata and SHA-256 must match immutable artifacts; code signing is a separate authenticity layer. The updater must consume the intended channel manifest and verify size/hash before replacement. Build directories are evidence until the new artifact is independently validated.", fr: "Le build du dépôt crée une application PyInstaller onedir, exécute des tests du paquet et valide le démarrage GUI avant un éventuel installateur Inno Setup. Métadonnées et SHA-256 doivent correspondre aux artefacts immuables ; la signature de code est une couche d’authenticité distincte. Le programme de mise à jour doit lire le manifeste du canal prévu et vérifier taille/hash avant remplacement. Les dossiers de build restent des preuves jusqu’à validation indépendante du nouvel artefact."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Launch the packaged executable from outside the source tree, exercise a harmless chat/settings path and compare its digest with the manifest candidate.", fr: "Lancez l’exécutable empaqueté hors de l’arbre source, testez un chemin conversation/réglages sans risque et comparez son empreinte au manifeste candidat."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Do not publish or delete the last known-good build before physical validation succeeds.", fr: "Ne publiez ni ne supprimez le dernier build valide avant la réussite du contrôle physique."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.windows-packaging",
            alt: GuideText(en: "OSIA visual explaining windows packaging.", fr: "Visuel OSIA expliquant empaquetage windows."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.android-packaging",
          trackId: "osia-advanced",
          order: 35,
          title: GuideText(en: "Android packaging", fr: "Empaquetage Android"),
          subtitle: GuideText(en: "Android releases bind Flutter output, version metadata, signing and store artifacts into one auditable result.", fr: "Les versions Android relient sortie Flutter, métadonnées de version, signature et artefacts de store en un résultat vérifiable."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Record the validated Flutter version with the build evidence. Increment versionName for the user release and versionCode for every uploaded build. Use release signing from ignored local configuration, build APK and AAB with production defines, inspect the bundle with bundletool, and verify application ID, minimum/target SDK and ABIs. R8 output includes a mapping to retain; keep native symbols when generated. Play App Signing protects the distribution key while the upload key signs submissions promoted deliberately through internal, closed, open and production tracks.", fr: "Consignez la version Flutter validée avec les preuves du build. Incrémentez versionName pour la version utilisateur et versionCode pour chaque envoi. Utilisez la signature release depuis une configuration locale ignorée, construisez APK et AAB avec les paramètres production, inspectez le bundle avec bundletool, puis vérifiez identifiant, SDK minimal/cible et ABI. Conservez le mapping R8 et les symboles natifs générés. Play App Signing protège la clé de distribution tandis que la clé d’envoi signe les soumissions promues consciemment entre canaux interne, fermé, ouvert et production."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Install the signed release APK on a compatible device, validate pairing and reconnection, then inspect the AAB before any store upload.", fr: "Installez l’APK release signé sur un appareil compatible, validez association et reconnexion, puis inspectez l’AAB avant tout envoi au store."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Never print or copy keystore passwords into logs, commands committed to Git or release notes.", fr: "N’affichez ni ne copiez les mots de passe du keystore dans les journaux, commandes suivies ou notes de version."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.android-packaging",
            alt: GuideText(en: "OSIA visual explaining android packaging.", fr: "Visuel OSIA expliquant empaquetage android."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.worker-site-deployment",
          trackId: "osia-advanced",
          order: 36,
          title: GuideText(en: "Worker and site deployment", fr: "Déploiement Worker et site"),
          subtitle: GuideText(en: "Worker, object storage and public-site updates are separate deployments joined by channel metadata.", fr: "Worker, stockage objet et site public sont des déploiements séparés reliés par les métadonnées de canal."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Validate Worker configuration, bindings, Durable Object migrations and compatibility before deployment. Upload immutable artifacts to R2 under versioned keys, then publish a small internal-preview or stable channel manifest with version, URL, size and SHA-256 only after verification. osia.space presents authoritative availability and release metadata without claiming platforms or channels that are not public. Rollback restores a known-good Worker or manifest pointer; it never overwrites an immutable version.", fr: "Validez configuration Worker, bindings, migrations Durable Object et compatibilité avant déploiement. Envoyez les artefacts immuables dans R2 sous des clés versionnées, puis publiez le manifeste du canal aperçu interne ou stable avec version, URL, taille et SHA-256 seulement après vérification. osia.space présente disponibilité et métadonnées réelles sans annoncer de plateforme ou canal non public. Le retour arrière restaure un Worker connu ou un pointeur de manifeste ; il ne remplace jamais une version immuable."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Deploy to a non-production environment, verify rendezvous and blind relay behavior, then check the exact manifest URL from a clean client.", fr: "Déployez dans un environnement hors production, vérifiez rendez-vous et relais aveugle, puis contrôlez l’URL exacte du manifeste depuis un client propre."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Repository access does not imply authorization to deploy or publish.", fr: "L’accès au dépôt n’implique pas l’autorisation de déployer ou publier."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.worker-site-deployment",
            alt: GuideText(en: "OSIA visual explaining worker and site deployment.", fr: "Visuel OSIA expliquant déploiement worker et site."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.release-process",
          trackId: "osia-advanced",
          order: 37,
          title: GuideText(en: "Release process", fr: "Processus de livraison"),
          subtitle: GuideText(en: "Release order prevents metadata from pointing at an artifact that is missing or unverified.", fr: "L’ordre de livraison empêche les métadonnées de pointer vers un artefact absent ou non vérifié."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Audit and prepare versions, run all tests, then create targeted local commits and physical-review builds. After approval, fetch and recheck divergence, push normally, build final artifacts from the pushed commits, and perform a physical update test. Upload immutable files, update the channel manifest, then update osia.space metadata. Promote Android through Google Play testing separately; iOS/TestFlight follows its own signing and review process. Monitor rollout and prune only superseded completed evidence while keeping the known-good and ambiguous builds.", fr: "Auditez et préparez les versions, lancez tous les tests, puis créez les commits locaux ciblés et les builds de revue physique. Après approbation, faites fetch et revérifiez la divergence, poussez normalement, construisez les artefacts finaux depuis les commits poussés et testez physiquement la mise à jour. Envoyez les fichiers immuables, actualisez le manifeste puis les métadonnées osia.space. Promouvez Android séparément via les tests Google Play ; iOS/TestFlight suit son propre processus de signature et revue. Surveillez le déploiement et ne supprimez que les preuves terminées remplacées."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Use a written checklist with one evidence path or digest beside every completed gate.", fr: "Utilisez une liste écrite avec un chemin de preuve ou une empreinte pour chaque jalon terminé."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "A successful local build is a candidate, not a published release.", fr: "Un build local réussi est un candidat, pas une version publiée."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.release-process",
            alt: GuideText(en: "OSIA visual explaining release process.", fr: "Visuel OSIA expliquant processus de livraison."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.security-model",
          trackId: "osia-advanced",
          order: 38,
          title: GuideText(en: "Security model", fr: "Modèle de sécurité"),
          subtitle: GuideText(en: "OSIA combines local ownership, authenticated transports, least privilege and effect-integrity barriers at sensitive boundaries.", fr: "OSIA combine propriété locale, transports authentifiés, moindre privilège et barrières d’intégrité d’effet aux frontières sensibles."),
          bodyBlocks: <GuideText>[
            GuideText(en: "Pairing establishes mobile trust, device identity and session keys; encrypted transports protect content, while a blind Worker relay routes ciphertext without plaintext. Secrets stay in ignored stores or approved bindings, logs are redacted, files are validated, and replay/sequence guards reject stale traffic. Tools are allowlisted and risky actions keep effect-integrity barriers. Signed metadata, size and SHA-256 protect update integrity. External AI providers still receive content required for configured requests under their own policies.", fr: "L’association établit confiance mobile, identité et clés de session ; les transports chiffrés protègent le contenu, tandis qu’un relais Worker aveugle route le chiffré sans texte clair. Les secrets restent dans des magasins ignorés ou bindings approuvés, les journaux sont masqués, les fichiers validés et les gardes de rejeu/séquence refusent l’ancien trafic. Les outils sont sur liste explicite et les actions risquées gardent des barrières d’intégrité d’effet. Métadonnées signées, taille et SHA-256 protègent l’intégrité des mises à jour. Les fournisseurs IA externes reçoivent néanmoins le contenu nécessaire selon leurs règles."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Threat-model a stolen pairing token, replayed frame, malicious filename, compromised provider key and untrusted MCP write separately.", fr: "Modélisez séparément vol de jeton d’association, trame rejouée, nom malveillant, clé fournisseur compromise et écriture MCP non fiable."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Encryption in transit does not replace endpoint security, backups or provider governance.", fr: "Le chiffrement en transit ne remplace ni sécurité des terminaux, ni sauvegardes, ni gouvernance fournisseur."),
            ),
          ],
          visual: GuideVisual(
            kind: "callout",
            key: "advanced.security-model",
            alt: GuideText(en: "OSIA visual explaining security model.", fr: "Visuel OSIA expliquant modèle de sécurité."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.developer-troubleshooting",
          trackId: "osia-advanced",
          order: 39,
          title: GuideText(en: "Developer troubleshooting", fr: "Dépannage développeur"),
          subtitle: GuideText(en: "Troubleshooting follows the failing boundary from observable symptom to the smallest reproducible contract.", fr: "Le dépannage suit la frontière défaillante depuis le symptôme observable jusqu’au plus petit contrat reproductible."),
          bodyBlocks: <GuideText>[
            GuideText(en: "For startup, distinguish a port conflict, stale process, wrong profile, missing frozen import or missing PyInstaller asset. For mobile, separate pairing mismatch, WebSocket disconnect, ICE or STUN failure, expected relay fallback and a duplicate handshake. For Android, check app-signature mismatch and versionCode conflict. For tests, identify developer-profile dependence and any runtime file appearing unexpectedly in source. For providers, distinguish image rejection from authentication/quota; for schedules, verify syntax, due time and that the PC was running. Sanitize logs and preserve evidence before cleanup.", fr: "Au démarrage, distinguez conflit de port, processus obsolète, mauvais profil, import frozen manquant ou asset PyInstaller absent. Pour le mobile, séparez association incohérente, déconnexion WebSocket, échec ICE ou STUN, repli normal vers le relais et handshake dupliqué. Pour Android, vérifiez signature d’app et conflit versionCode. Pour les tests, repérez la dépendance au profil développeur et tout fichier d’exécution apparu dans les sources. Pour les fournisseurs, distinguez rejet d’image et auth/quota ; pour les tâches, vérifiez syntaxe, échéance et PC actif. Masquez les journaux et conservez les preuves."),
          ],
          callouts: <GuideCallout>[
            GuideCallout(
              kind: "example",
              title: GuideText(en: "In practice", fr: "En pratique"),
              body: GuideText(en: "Reduce a reconnect failure to one synthetic request ID and timeline before changing retry code.", fr: "Réduisez un échec de reconnexion à un identifiant de requête et une chronologie fictifs avant de modifier les tentatives."),
            ),
            GuideCallout(
              kind: "remember",
              title: GuideText(en: "Remember", fr: "À retenir"),
              body: GuideText(en: "Do not treat a retry that hides duplication or data loss as a fix.", fr: "Ne considérez pas comme correctif une nouvelle tentative qui masque duplication ou perte de données."),
            ),
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.developer-troubleshooting",
            alt: GuideText(en: "OSIA visual explaining developer troubleshooting.", fr: "Visuel OSIA expliquant dépannage développeur."),
            asset: null,
          ),
          legacyIds: <String>[
          ],
        ),
        GuideSlide(
          id: "advanced.glossary-ai",
          trackId: "osia-advanced",
          order: 40,
          title: GuideText(en: "Glossary: AI and tools", fr: "Glossaire : IA et outils"),
          subtitle: GuideText(en: "Stable terms make the guide, UI, protocol tests and release evidence easier to compare. Provider: service exposing models; model: selected AI implementation; API: programmatic service contract; token: bounded credential or model text unit, by context; context: input retained for a model turn; thinking: supported reasoning effort; MCP: Model Context Protocol; DCR: OAuth dynamic client registration; OAuth: delegated authorization; cron: schedule expression; WebSocket: persistent bidirectional connection.", fr: "Des termes stables facilitent la comparaison entre guide, interface, tests de protocole et preuves de livraison. Fournisseur : service exposant des modèles ; modèle : implémentation IA choisie ; API : contrat programmable ; token : identifiant borné ou unité de texte selon le contexte ; contexte : entrée d’un tour ; thinking : effort de raisonnement pris en charge ; MCP : Model Context Protocol ; DCR : enregistrement dynamique OAuth ; OAuth : autorisation déléguée ; cron : expression de planification ; WebSocket : connexion bidirectionnelle persistante."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
          ],
          visual: GuideVisual(
            kind: "native",
            key: "advanced.glossary-ai",
            alt: GuideText(en: "OSIA visual explaining glossary: ai and tools.", fr: "Visuel OSIA expliquant glossaire : ia et outils."),
            asset: null,
          ),
          legacyIds: <String>[
            "advanced.glossary",
          ],
        ),
        GuideSlide(
          id: "advanced.glossary-transport",
          trackId: "osia-advanced",
          order: 41,
          title: GuideText(en: "Glossary: transport", fr: "Glossaire : transport"),
          subtitle: GuideText(en: "E2E: endpoint-to-endpoint encryption; LAN: local area network; P2P: direct peer-to-peer path; WebRTC: real-time peer transport; SDP: WebRTC session description; ICE: WebRTC connectivity process; STUN: public-path discovery; TURN: WebRTC relay service; signaling: offer, answer and candidate exchange.", fr: "E2E : chiffrement de bout en bout ; LAN : réseau local ; P2P : chemin direct entre pairs ; WebRTC : transport temps réel entre pairs ; SDP : description de session WebRTC ; ICE : recherche de connectivité ; STUN : découverte du chemin public ; TURN : relais WebRTC ; signalisation : échange offre, réponse et candidats."),
          bodyBlocks: <GuideText>[
          ],
          callouts: <GuideCallout>[
          ],
          visual: GuideVisual(
            kind: "diagram",
            key: "advanced.glossary-transport",
            alt: GuideText(en: "OSIA visual explaining glossary: transport.", fr: "Visuel OSIA expliquant glossaire : transport."),
            asset: null,
          ),
          legacyIds: <String>[
            "advanced.glossary",
          ],
        ),
        GuideSlide(
          id: "advanced.glossary-delivery",
          trackId: "osia-advanced",
